window.SW_LISTEN = window.SW_LISTEN || {};
window.SW_LISTEN.en = [
{ id: "p01", level: "A2", title: "Mein erster Tag in London", people: ["Host","Maria"], lines: [
  ["Host","Hello and welcome to 'Easy English Stories'. Today my guest is Maria. She moved from Spain to London last year. Hi, Maria!","Hallo und willkommen bei „Easy English Stories“. Heute ist Maria zu Gast. Sie ist letztes Jahr von Spanien nach London gezogen. Hallo, Maria!"],
  ["Maria","Hi! Thanks for having me.","Hi! Danke für die Einladung."],
  ["Host","So, tell us about your first day in London.","Erzähl uns von deinem ersten Tag in London."],
  ["Maria","Well, it was a Monday in October. It was cold and it rained all day. I didn't have an umbrella, so I bought one at the station. It cost twelve pounds!","Also, es war ein Montag im Oktober. Es war kalt und hat den ganzen Tag geregnet. Ich hatte keinen Schirm, also habe ich am Bahnhof einen gekauft. Er hat zwölf Pfund gekostet!"],
  ["Host","That's expensive! Where did you live?","Das ist teuer! Wo hast du gewohnt?"],
  ["Maria","I lived with a friend in a small flat in the east of the city. My room was very small, but the kitchen was nice.","Ich habe bei einer Freundin in einer kleinen Wohnung im Osten der Stadt gewohnt. Mein Zimmer war sehr klein, aber die Küche war schön."],
  ["Host","Was your English good at that time?","War dein Englisch damals gut?"],
  ["Maria","Not really. I understood a lot, but I was nervous when I had to speak. On the first day I went to a café and asked for a 'white coffee'. The waiter didn't understand me because of my accent.","Nicht wirklich. Ich habe viel verstanden, aber ich war nervös, wenn ich sprechen musste. Am ersten Tag bin ich in ein Café gegangen und habe einen „Kaffee mit Milch“ bestellt. Der Kellner hat mich wegen meines Akzents nicht verstanden."],
  ["Host","Oh no! What did you do?","Oh nein! Was hast du gemacht?"],
  ["Maria","I pointed at the milk and smiled. He laughed and said, 'Ah, a white coffee!' After that, we became friends. I went to that café every morning.","Ich habe auf die Milch gezeigt und gelächelt. Er hat gelacht und gesagt: „Ah, ein Kaffee mit Milch!“ Danach sind wir Freunde geworden. Ich bin jeden Morgen in das Café gegangen."],
  ["Host","That's a lovely story. And now? Do you like London?","Das ist eine schöne Geschichte. Und jetzt? Magst du London?"],
  ["Maria","Yes, I love it. The weather is still bad, but the people are friendly and there's always something to do. And my English is much better now!","Ja, ich liebe es. Das Wetter ist immer noch schlecht, aber die Leute sind freundlich, und es gibt immer etwas zu tun. Und mein Englisch ist jetzt viel besser!"],
  ["Host","Thank you, Maria. And thank you for listening. See you next time!","Danke, Maria. Und danke fürs Zuhören. Bis zum nächsten Mal!"]],
  questions: [
  ["Wann kam Maria nach London?","An einem Montag im Oktober",["An einem Freitag im Juli","Im Dezember","Vor fünf Jahren"]],
  ["Was hat sie am Bahnhof gekauft?","Einen Regenschirm",["Eine Fahrkarte","Einen Kaffee","Eine Jacke"]],
  ["Warum hat der Kellner sie nicht verstanden?","Wegen ihres Akzents",["Er sprach kein Englisch","Es war zu laut","Sie hat Spanisch gesprochen"]],
  ["Was wurde aus dem Kellner?","Ein Freund",["Ihr Chef","Ihr Mitbewohner","Nichts"]],
  ["Was gefällt ihr an London?","Die freundlichen Leute und dass immer etwas los ist",["Das Wetter","Die billigen Preise","Die Ruhe"]]]},
{ id: "p02", level: "A2", title: "Ein Wochenende ohne Handy", people: ["Host","Ben"], lines: [
  ["Host","Welcome back to 'Easy English Stories'. Ben, you tried something unusual last weekend. What was it?","Willkommen zurück bei „Easy English Stories“. Ben, du hast letztes Wochenende etwas Ungewöhnliches ausprobiert. Was war das?"],
  ["Ben","I didn't use my phone for two days. I switched it off on Friday evening and put it in a drawer.","Ich habe zwei Tage lang mein Handy nicht benutzt. Ich habe es am Freitagabend ausgeschaltet und in eine Schublade gelegt."],
  ["Host","Why did you do that?","Warum hast du das gemacht?"],
  ["Ben","I was always tired and I looked at my phone more than four hours a day. I wanted to see what happens without it.","Ich war immer müde und habe mehr als vier Stunden am Tag aufs Handy geschaut. Ich wollte sehen, was ohne passiert."],
  ["Host","And how was Saturday?","Und wie war der Samstag?"],
  ["Ben","The morning was strange. I wanted to check the weather, but I couldn't! So I just looked out of the window. Then I went for a long walk in the forest.","Der Morgen war komisch. Ich wollte das Wetter checken, konnte aber nicht! Also habe ich einfach aus dem Fenster geschaut. Dann bin ich lange im Wald spazieren gegangen."],
  ["Host","Did you miss anything important?","Hast du etwas Wichtiges verpasst?"],
  ["Ben","My mum called three times. When she couldn't reach me, she came to my flat! She was a bit worried, but then we had lunch together. That was nice.","Meine Mutter hat dreimal angerufen. Als sie mich nicht erreicht hat, ist sie zu meiner Wohnung gekommen! Sie war etwas besorgt, aber dann haben wir zusammen zu Mittag gegessen. Das war schön."],
  ["Host","And on Sunday?","Und am Sonntag?"],
  ["Ben","On Sunday I read a book – the first book in a year – and I slept nine hours. I felt much better.","Am Sonntag habe ich ein Buch gelesen – das erste Buch seit einem Jahr – und neun Stunden geschlafen. Ich habe mich viel besser gefühlt."],
  ["Host","Will you do it again?","Machst du das wieder?"],
  ["Ben","Yes, but next time I'm going to tell my mum first!","Ja, aber nächstes Mal sage ich vorher meiner Mutter Bescheid!"]],
  questions: [
  ["Wie lange hat Ben das Handy nicht benutzt?","Zwei Tage",["Eine Woche","Einen Tag","Vier Stunden"]],
  ["Warum hat er das gemacht?","Er war müde und hat zu viel aufs Handy geschaut",["Sein Handy war kaputt","Seine Mutter wollte es","Für eine Wette"]],
  ["Was hat er am Samstagmorgen gemacht?","Er ist im Wald spazieren gegangen",["Er hat ferngesehen","Er hat gearbeitet","Er ist einkaufen gegangen"]],
  ["Warum kam seine Mutter vorbei?","Sie hat ihn nicht erreicht und war besorgt",["Zu seinem Geburtstag","Sie brauchte Hilfe","Sie wollte das Handy holen"]],
  ["Was wird er nächstes Mal anders machen?","Seiner Mutter vorher Bescheid sagen",["Das Handy anlassen","Eine Woche machen","Nicht mehr in den Wald gehen"]]]},
{ id: "p03", level: "B1", title: "Wie ich Lokführer wurde", people: ["Host","Daniel"], lines: [
  ["Host","Welcome to 'Working Lives', the podcast about real jobs. My guest today is Daniel, a train driver from Manchester. Daniel, have you always wanted to drive trains?","Willkommen bei „Working Lives“, dem Podcast über echte Berufe. Mein Gast heute ist Daniel, Lokführer aus Manchester. Daniel, wolltest du schon immer Züge fahren?"],
  ["Daniel","Not at all! I used to work in a warehouse. I'd been there for eight years when the company closed down. Suddenly, I had no job and two kids to feed.","Überhaupt nicht! Ich habe früher in einem Lager gearbeitet. Ich war acht Jahre dort, als die Firma geschlossen hat. Plötzlich hatte ich keinen Job und zwei Kinder zu ernähren."],
  ["Host","That must have been hard.","Das muss hart gewesen sein."],
  ["Daniel","It was. But a friend told me that the railway was looking for drivers. I applied, even though I didn't think I had a chance.","Das war es. Aber ein Freund erzählte mir, dass die Bahn Lokführer sucht. Ich habe mich beworben, obwohl ich nicht dachte, dass ich eine Chance hätte."],
  ["Host","What was the selection process like?","Wie lief das Auswahlverfahren ab?"],
  ["Daniel","Tough. There were concentration tests, a medical, and an interview. Only about one in ten applicants gets through. When they called me to say I'd passed, I couldn't believe it.","Schwierig. Es gab Konzentrationstests, eine ärztliche Untersuchung und ein Vorstellungsgespräch. Nur etwa einer von zehn Bewerbern kommt durch. Als sie anriefen und sagten, ich hätte bestanden, konnte ich es nicht glauben."],
  ["Host","And then the training started?","Und dann begann die Ausbildung?"],
  ["Daniel","Yes, it took about a year. You have to learn every route by heart – every signal, every speed limit, every station. I studied in the evenings after the kids had gone to bed.","Ja, sie dauerte etwa ein Jahr. Man muss jede Strecke auswendig lernen – jedes Signal, jedes Tempolimit, jeden Bahnhof. Ich habe abends gelernt, wenn die Kinder im Bett waren."],
  ["Host","What's the best thing about the job?","Was ist das Beste an dem Job?"],
  ["Daniel","The responsibility, strangely enough. I'm carrying hundreds of people, and I take that seriously. Also the views – early in the morning, when the sun comes up over the hills, it's beautiful.","Seltsamerweise die Verantwortung. Ich befördere Hunderte Menschen, und das nehme ich ernst. Und die Aussicht – frühmorgens, wenn die Sonne über den Hügeln aufgeht, ist es wunderschön."],
  ["Host","And the worst?","Und das Schlimmste?"],
  ["Daniel","The shifts. Sometimes I start at four in the morning, sometimes I finish at midnight. It's hard on family life. But the pay is good, and I'm proud of what I do.","Die Schichten. Manchmal fange ich um vier Uhr morgens an, manchmal höre ich um Mitternacht auf. Das ist hart fürs Familienleben. Aber die Bezahlung ist gut, und ich bin stolz auf das, was ich tue."],
  ["Host","Any advice for people who are thinking about changing careers?","Hast du einen Rat für Leute, die über einen Berufswechsel nachdenken?"],
  ["Daniel","Just apply. The worst thing that can happen is that they say no. If I hadn't tried, I'd probably still be looking for work.","Einfach bewerben. Das Schlimmste, was passieren kann, ist ein Nein. Hätte ich es nicht versucht, würde ich wahrscheinlich immer noch Arbeit suchen."]],
  questions: [
  ["Was hat Daniel früher gemacht?","Er hat in einem Lager gearbeitet",["Er war Busfahrer","Er war Lehrer","Er war arbeitslos"]],
  ["Wie hat er von der Stelle erfahren?","Von einem Freund",["Aus der Zeitung","Vom Arbeitsamt","Im Internet"]],
  ["Wie viele Bewerber schaffen das Auswahlverfahren?","Etwa einer von zehn",["Die Hälfte","Fast alle","Einer von hundert"]],
  ["Was muss man in der Ausbildung auswendig lernen?","Jede Strecke mit Signalen und Tempolimits",["Alle Fahrpläne","Alle Fahrgastnamen","Die Technik jeder Lok"]],
  ["Was ist für ihn das Schwierigste?","Die Schichten",["Die Bezahlung","Die Kollegen","Die Verantwortung"]]]},
{ id: "p04", level: "B1", title: "Lebensmittel retten", people: ["Host","Sophie"], lines: [
  ["Host","Welcome to 'Green Living'. Did you know that the average household throws away around 80 kilos of food a year? My guest Sophie runs a food-sharing group. Sophie, how did it start?","Willkommen bei „Green Living“. Wusstet ihr, dass ein durchschnittlicher Haushalt rund 80 Kilo Lebensmittel im Jahr wegwirft? Mein Gast Sophie leitet eine Foodsharing-Gruppe. Sophie, wie hat das angefangen?"],
  ["Sophie","A few years ago I worked in a supermarket. Every evening we had to throw away bread, fruit and vegetables that were perfectly fine. It made me angry.","Vor ein paar Jahren habe ich in einem Supermarkt gearbeitet. Jeden Abend mussten wir Brot, Obst und Gemüse wegwerfen, das völlig in Ordnung war. Das hat mich wütend gemacht."],
  ["Host","So what did you do?","Und was hast du gemacht?"],
  ["Sophie","I asked the manager if I could take the food and give it away. At first he said no, because of the rules. But after a few weeks he agreed, as long as we picked it up ourselves.","Ich habe den Filialleiter gefragt, ob ich die Lebensmittel mitnehmen und verschenken darf. Erst hat er wegen der Vorschriften Nein gesagt. Aber nach ein paar Wochen hat er zugestimmt, solange wir sie selbst abholen."],
  ["Host","How many people are involved now?","Wie viele Leute machen jetzt mit?"],
  ["Sophie","We have about sixty volunteers and we work with twelve shops and bakeries. Every day someone collects the food and brings it to a fridge in the town centre. Anyone can take what they need.","Wir haben etwa sechzig Ehrenamtliche und arbeiten mit zwölf Läden und Bäckereien zusammen. Jeden Tag holt jemand die Lebensmittel ab und bringt sie zu einem Kühlschrank in der Innenstadt. Jeder kann nehmen, was er braucht."],
  ["Host","Isn't that a problem with hygiene?","Ist das nicht ein Hygieneproblem?"],
  ["Sophie","We follow strict rules. No raw meat or fish, and we check the fridge twice a day. If something doesn't look good, we throw it away – but that happens very rarely.","Wir halten uns an strenge Regeln. Kein rohes Fleisch oder Fisch, und wir kontrollieren den Kühlschrank zweimal täglich. Wenn etwas nicht gut aussieht, werfen wir es weg – aber das passiert sehr selten."],
  ["Host","What can listeners do at home to waste less food?","Was können die Zuhörer zu Hause tun, um weniger zu verschwenden?"],
  ["Sophie","Three simple things. First, make a shopping list and stick to it. Second, remember that 'best before' doesn't mean 'bad after' – use your eyes and nose. And third, freeze leftovers instead of throwing them away.","Drei einfache Dinge. Erstens: eine Einkaufsliste schreiben und sich daran halten. Zweitens: Daran denken, dass „mindestens haltbar bis“ nicht „danach schlecht“ heißt – nutzt Augen und Nase. Und drittens: Reste einfrieren statt wegwerfen."],
  ["Host","Great tips. Thank you, Sophie!","Tolle Tipps. Danke, Sophie!"]],
  questions: [
  ["Wie viel Essen wirft ein Haushalt laut Podcast pro Jahr weg?","Rund 80 Kilo",["Rund 8 Kilo","Rund 800 Kilo","Rund 18 Kilo"]],
  ["Warum hat Sophie angefangen?","Im Supermarkt wurde gutes Essen weggeworfen",["Sie hatte selbst kein Geld","Ihre Freundin hatte die Idee","Wegen einer Fernsehsendung"]],
  ["Wohin kommen die geretteten Lebensmittel?","In einen Kühlschrank in der Innenstadt",["In Sophies Wohnung","Ins Krankenhaus","Zurück in den Laden"]],
  ["Was wird NICHT verteilt?","Rohes Fleisch und Fisch",["Brot","Obst","Gemüse"]],
  ["Was bedeutet „best before“ laut Sophie?","Nicht automatisch schlecht danach",["Sofort wegwerfen","Nur noch kochen","Nur für Tiere"]]]},
{ id: "p05", level: "B2", title: "Der Ausfall in der Nachtschicht", people: ["Host","Kerstin"], lines: [
  ["Host","This is 'Shop Floor Stories', where people from industry tell us about their toughest days. Kerstin is a maintenance technician at a car parts plant. Kerstin, what happened?","Das ist „Shop Floor Stories“, wo Menschen aus der Industrie von ihren härtesten Tagen erzählen. Kerstin ist Instandhaltungstechnikerin in einem Autozulieferwerk. Kerstin, was ist passiert?"],
  ["Kerstin","It was a night shift in January, around two in the morning. I'd just sat down with a coffee when the alarm went off. The main press had stopped, and the whole line came to a standstill.","Es war eine Nachtschicht im Januar, gegen zwei Uhr morgens. Ich hatte mich gerade mit einem Kaffee hingesetzt, als der Alarm losging. Die Hauptpresse war stehen geblieben, und die ganze Linie stand still."],
  ["Host","How serious was it?","Wie ernst war es?"],
  ["Kerstin","Very. We had a truck leaving for a customer at six, and if we'd missed it, their assembly line would have stopped too. That costs thousands of euros per minute.","Sehr. Um sechs sollte ein LKW zu einem Kunden fahren, und hätten wir den verpasst, wäre deren Montagelinie auch stehen geblieben. Das kostet Tausende Euro pro Minute."],
  ["Host","What was the problem?","Was war das Problem?"],
  ["Kerstin","At first, the error message made no sense. It said the hydraulic pressure was too low, but the gauge looked normal. We spent almost an hour checking pumps and valves before we found it: a tiny sensor cable had been damaged, probably by vibration. The machine thought there was a problem, but there wasn't.","Zuerst ergab die Fehlermeldung keinen Sinn. Sie besagte, der Hydraulikdruck sei zu niedrig, aber das Manometer sah normal aus. Wir haben fast eine Stunde Pumpen und Ventile geprüft, bevor wir es fanden: Ein winziges Sensorkabel war beschädigt worden, wahrscheinlich durch Vibration. Die Maschine dachte, es gäbe ein Problem, aber es gab keins."],
  ["Host","So it was a false alarm, in a way.","Also gewissermaßen ein Fehlalarm."],
  ["Kerstin","Exactly. Replacing the cable took ten minutes. Finding it took the time. By four, the line was running again, and the operators worked flat out. The truck left at ten past six – only ten minutes late.","Genau. Das Kabel zu ersetzen dauerte zehn Minuten. Es zu finden kostete die Zeit. Um vier lief die Linie wieder, und die Bediener haben Vollgas gegeben. Der LKW fuhr um zehn nach sechs – nur zehn Minuten zu spät."],
  ["Host","What did you learn from it?","Was hast du daraus gelernt?"],
  ["Kerstin","Two things. First, don't trust an error message blindly – check the obvious things, like cables, first. Second, we now inspect all sensor cables during the monthly maintenance. If we'd done that before, the breakdown probably wouldn't have happened.","Zwei Dinge. Erstens: einer Fehlermeldung nicht blind vertrauen – zuerst das Offensichtliche prüfen, zum Beispiel Kabel. Zweitens: Wir prüfen jetzt bei der monatlichen Wartung alle Sensorkabel. Hätten wir das vorher gemacht, wäre der Ausfall wahrscheinlich nicht passiert."],
  ["Host","And the coffee?","Und der Kaffee?"],
  ["Kerstin","Stone cold, of course. I drank it anyway.","Eiskalt natürlich. Ich hab ihn trotzdem getrunken."]],
  questions: [
  ["Wann passierte der Ausfall?","Gegen 2 Uhr nachts im Januar",["Morgens um 6","Mittags im Sommer","Am Wochenende"]],
  ["Warum war es so dringend?","Ein LKW musste um 6 Uhr zu einem Kunden",["Der Chef kam zu Besuch","Ein Audit stand an","Die Schicht endete"]],
  ["Was war die eigentliche Ursache?","Ein beschädigtes Sensorkabel",["Eine defekte Pumpe","Zu wenig Hydrauliköl","Ein Bedienfehler"]],
  ["Wie spät fuhr der LKW los?","Zehn Minuten zu spät",["Pünktlich","Zwei Stunden zu spät","Gar nicht"]],
  ["Was wird jetzt anders gemacht?","Sensorkabel werden monatlich geprüft",["Es gibt keine Nachtschicht mehr","Die Presse wurde ersetzt","Es gibt mehr Personal"]]]},
{ id: "p06", level: "B2", title: "Sprachen lernen als Erwachsener", people: ["Host","Dr. Patel"], lines: [
  ["Host","Welcome to 'Mind Matters'. Many adults believe they're too old to learn a language. Dr. Patel, a linguist, is here to tell us whether that's true.","Willkommen bei „Mind Matters“. Viele Erwachsene glauben, sie seien zu alt, um eine Sprache zu lernen. Dr. Patel, Sprachwissenschaftlerin, sagt uns, ob das stimmt."],
  ["Dr. Patel","It's one of the most common myths. Children do have an advantage with pronunciation – they pick up accents almost effortlessly. But adults are actually faster learners in many other areas, especially grammar and vocabulary.","Das ist einer der häufigsten Mythen. Kinder haben tatsächlich einen Vorteil bei der Aussprache – sie übernehmen Akzente fast mühelos. Aber Erwachsene lernen in vielen anderen Bereichen sogar schneller, vor allem bei Grammatik und Wortschatz."],
  ["Host","Why is that?","Warum?"],
  ["Dr. Patel","Because adults can think about rules, make connections and use strategies. If you already speak German, for example, you'll recognise thousands of English words that are similar. Children can't use that kind of knowledge so consciously.","Weil Erwachsene über Regeln nachdenken, Verbindungen herstellen und Strategien nutzen können. Wer zum Beispiel schon Deutsch spricht, erkennt Tausende englische Wörter, die ähnlich sind. Kinder können solches Wissen nicht so bewusst nutzen."],
  ["Host","So what holds adults back?","Was hält Erwachsene dann zurück?"],
  ["Dr. Patel","Mostly time and fear. Adults are busy, and they're afraid of making mistakes and looking silly. But mistakes are essential – they show your brain what to correct.","Vor allem Zeit und Angst. Erwachsene haben viel zu tun und haben Angst, Fehler zu machen und sich zu blamieren. Aber Fehler sind unverzichtbar – sie zeigen dem Gehirn, was es korrigieren muss."],
  ["Host","What's the most effective way to learn?","Was ist der effektivste Weg zu lernen?"],
  ["Dr. Patel","Short, regular practice beats long, irregular sessions. Fifteen minutes a day is far better than two hours on a Sunday. That's because of something called spaced repetition – you review words just before you'd forget them.","Kurzes, regelmäßiges Üben schlägt lange, unregelmäßige Einheiten. Fünfzehn Minuten am Tag sind viel besser als zwei Stunden am Sonntag. Das liegt an der sogenannten verteilten Wiederholung – man wiederholt Wörter kurz bevor man sie vergessen würde."],
  ["Host","And what about speaking?","Und das Sprechen?"],
  ["Dr. Patel","That's the part most learners neglect. You can know two thousand words and still freeze in a conversation. I'd recommend speaking from day one – even if it's only to yourself, or reading texts aloud. And as soon as possible, find real people to talk to.","Das ist der Teil, den die meisten vernachlässigen. Man kann zweitausend Wörter kennen und trotzdem im Gespräch erstarren. Ich empfehle, vom ersten Tag an zu sprechen – auch wenn es nur mit sich selbst ist oder man Texte laut vorliest. Und sobald wie möglich echte Gesprächspartner suchen."],
  ["Host","So, is anyone too old?","Also, ist irgendjemand zu alt?"],
  ["Dr. Patel","I've had students in their seventies who reached a very good level. Age matters far less than motivation and consistency.","Ich hatte Studierende über siebzig, die ein sehr gutes Niveau erreicht haben. Das Alter zählt viel weniger als Motivation und Beständigkeit."]],
  questions: [
  ["Worin haben Kinder einen Vorteil?","Bei der Aussprache",["Bei der Grammatik","Beim Wortschatz","In allem"]],
  ["Warum lernen Erwachsene manches schneller?","Sie können Regeln und Verbindungen bewusst nutzen",["Sie haben mehr Zeit","Ihr Gedächtnis ist besser","Sie machen weniger Fehler"]],
  ["Was hält Erwachsene laut Dr. Patel zurück?","Zeit und Angst vor Fehlern",["Ihr Alter","Zu wenig Geld","Schlechte Lehrer"]],
  ["Was ist besser?","Täglich 15 Minuten",["Sonntags zwei Stunden","Einmal im Monat einen Tag","Nur in den Ferien"]],
  ["Was zählt laut ihr am meisten?","Motivation und Beständigkeit",["Das Alter","Talent","Ein teurer Kurs"]]]},
{ id: "p07", level: "C1", title: "Arbeit mit KI: Fluch oder Segen?", people: ["Host","Marcus","Lena"], lines: [
  ["Host","Welcome to 'Future of Work'. Today we're debating whether artificial intelligence will make our jobs better or simply make many of us redundant. With me are Marcus, a union representative, and Lena, who manages digital transformation at a logistics firm.","Willkommen bei „Future of Work“. Heute diskutieren wir, ob künstliche Intelligenz unsere Jobs besser macht oder viele von uns einfach überflüssig. Bei mir sind Marcus, Gewerkschaftsvertreter, und Lena, die bei einer Logistikfirma die digitale Transformation leitet."],
  ["Lena","Let me start with what we've actually seen. Since introducing AI-based route planning, our drivers spend far less time stuck in traffic, and overtime has dropped by around a fifth. Nobody lost their job – if anything, we're hiring.","Lassen Sie mich mit dem beginnen, was wir tatsächlich beobachtet haben. Seit wir KI-gestützte Routenplanung eingeführt haben, stehen unsere Fahrer deutlich seltener im Stau, und die Überstunden sind um etwa ein Fünftel gesunken. Niemand hat seinen Job verloren – wenn überhaupt, stellen wir ein."],
  ["Marcus","That's encouraging, and I don't doubt your figures. But your company is arguably an exception. In administrative roles – data entry, customer service, accounting – we're already seeing positions quietly disappear. Not through dismissals, but through jobs that simply aren't replaced when people retire.","Das ist ermutigend, und ich bezweifle Ihre Zahlen nicht. Aber Ihre Firma ist wohl eine Ausnahme. In Verwaltungsjobs – Dateneingabe, Kundenservice, Buchhaltung – sehen wir schon, wie Stellen still und leise verschwinden. Nicht durch Kündigungen, sondern weil Stellen beim Renteneintritt einfach nicht nachbesetzt werden."],
  ["Host","Lena, is that a fair point?","Lena, ist das ein berechtigter Punkt?"],
  ["Lena","Partly, yes. Some tasks will vanish, there's no denying that. But history suggests that new technology creates roles we can't yet imagine. Twenty years ago, nobody had heard of a data analyst in a warehouse. Now we have four.","Teilweise ja. Manche Aufgaben werden verschwinden, das lässt sich nicht leugnen. Aber die Geschichte zeigt, dass neue Technik Berufe schafft, die wir uns noch nicht vorstellen können. Vor zwanzig Jahren hatte niemand von einem Datenanalysten im Lager gehört. Jetzt haben wir vier."],
  ["Marcus","Granted. My concern is who gets those new jobs. A 55-year-old warehouse worker doesn't become a data analyst overnight. Unless companies invest seriously in retraining, we'll end up with winners and losers.","Zugegeben. Meine Sorge ist, wer diese neuen Jobs bekommt. Ein 55-jähriger Lagerarbeiter wird nicht über Nacht zum Datenanalysten. Wenn Firmen nicht ernsthaft in Umschulung investieren, wird es Gewinner und Verlierer geben."],
  ["Lena","On that, I completely agree. Having seen how quickly people adapt when they're given proper training, I'm convinced it's the single most important factor. Technology alone doesn't decide anything – people do.","Da stimme ich völlig zu. Nachdem ich gesehen habe, wie schnell Menschen sich anpassen, wenn sie richtig geschult werden, bin ich überzeugt, dass das der wichtigste Faktor ist. Technik allein entscheidet nichts – Menschen tun das."],
  ["Host","So, to sum up: AI will change most jobs, eliminate some and create others – and the outcome depends largely on whether employers and governments invest in people. Marcus, Lena, thank you both.","Zusammengefasst: KI wird die meisten Jobs verändern, manche abschaffen und andere schaffen – und das Ergebnis hängt weitgehend davon ab, ob Arbeitgeber und Staat in Menschen investieren. Marcus, Lena, danke euch beiden."]],
  questions: [
  ["Was hat KI-Routenplanung bei Lenas Firma bewirkt?","Weniger Stau und rund 20 % weniger Überstunden",["Viele Entlassungen","Höhere Spritkosten","Keine Veränderung"]],
  ["Wie verschwinden laut Marcus Stellen?","Sie werden bei Renteneintritt nicht nachbesetzt",["Durch Massenentlassungen","Durch Streiks","Durch Auslagerung ins Ausland"]],
  ["Welches Beispiel für einen neuen Beruf nennt Lena?","Datenanalyst im Lager",["KI-Trainer","Roboter-Mechaniker","Drohnenpilot"]],
  ["Worüber sind sich beide einig?","Umschulung ist entscheidend",["KI sollte verboten werden","Es gibt keine Verlierer","Ältere sollten früher in Rente"]],
  ["Wie lautet das Fazit des Moderators?","Das Ergebnis hängt von Investitionen in Menschen ab",["KI vernichtet alle Jobs","KI ändert nichts","Nur junge Leute profitieren"]]]},
{ id: "p08", level: "C1", title: "Warum wir schlecht schlafen", people: ["Host","Prof. Hughes"], lines: [
  ["Host","Welcome to 'Body & Mind'. Around a third of adults say they don't get enough sleep. Professor Hughes, you've researched sleep for twenty years. What's going wrong?","Willkommen bei „Body & Mind“. Rund ein Drittel der Erwachsenen sagt, nicht genug Schlaf zu bekommen. Professor Hughes, Sie erforschen Schlaf seit zwanzig Jahren. Was läuft schief?"],
  ["Prof. Hughes","Several things at once. Our bodies evolved to wake with the sun and sleep when it gets dark. Artificial light, screens and irregular working hours have disrupted that rhythm in ways we're only beginning to understand.","Mehreres gleichzeitig. Unser Körper hat sich so entwickelt, dass wir mit der Sonne aufwachen und bei Dunkelheit schlafen. Künstliches Licht, Bildschirme und unregelmäßige Arbeitszeiten haben diesen Rhythmus auf eine Weise gestört, die wir erst allmählich verstehen."],
  ["Host","Shift workers must be particularly affected.","Schichtarbeiter sind sicher besonders betroffen."],
  ["Prof. Hughes","They are. Night workers sleep, on average, one to two hours less than day workers, and the sleep they do get tends to be lighter. Over years, that's linked to a higher risk of heart disease, diabetes and depression – although I'd stress that it's a risk, not a certainty.","Ja. Nachtarbeiter schlafen im Schnitt ein bis zwei Stunden weniger als Tagarbeiter, und ihr Schlaf ist meist leichter. Über Jahre steht das mit einem höheren Risiko für Herzkrankheiten, Diabetes und Depression in Zusammenhang – wobei ich betonen möchte, dass es ein Risiko ist, keine Gewissheit."],
  ["Host","What can they do?","Was können sie tun?"],
  ["Prof. Hughes","Quite a lot, actually. Keep the bedroom completely dark – blackout curtains make a huge difference. Avoid bright light on the way home after a night shift; even sunglasses help. And try to keep a consistent routine, even on days off, as far as family life allows.","Tatsächlich ziemlich viel. Das Schlafzimmer komplett abdunkeln – Verdunkelungsvorhänge machen einen riesigen Unterschied. Nach der Nachtschicht auf dem Heimweg helles Licht meiden; selbst eine Sonnenbrille hilft. Und versuchen, einen gleichmäßigen Rhythmus zu halten, auch an freien Tagen, soweit das Familienleben es zulässt."],
  ["Host","And what about caffeine? Many people rely on it to get through a shift.","Und Koffein? Viele verlassen sich darauf, um eine Schicht durchzustehen."],
  ["Prof. Hughes","Caffeine is fine early in the shift, but its effect lasts much longer than people think – roughly six hours for half of it to wear off. A coffee at four in the morning may well be the reason you can't sleep at eight.","Koffein ist früh in der Schicht in Ordnung, aber seine Wirkung hält viel länger an, als man denkt – etwa sechs Stunden, bis die Hälfte abgebaut ist. Ein Kaffee um vier Uhr morgens kann gut der Grund sein, warum man um acht nicht schlafen kann."],
  ["Host","Finally, is there one piece of advice that applies to everyone?","Zum Schluss: Gibt es einen Rat, der für alle gilt?"],
  ["Prof. Hughes","Treat sleep as seriously as diet and exercise. We'd never boast about skipping meals, yet people still boast about getting by on five hours. Sleep isn't a luxury – it's the foundation everything else is built on.","Schlaf so ernst nehmen wie Ernährung und Bewegung. Niemand würde damit prahlen, Mahlzeiten auszulassen, aber mit fünf Stunden Schlaf prahlen die Leute immer noch. Schlaf ist kein Luxus – er ist das Fundament, auf dem alles andere aufbaut."]],
  questions: [
  ["Was hat laut Prof. Hughes den Schlafrhythmus gestört?","Künstliches Licht, Bildschirme, unregelmäßige Arbeitszeiten",["Zu viel Sport","Schlechte Matratzen","Zu warme Zimmer"]],
  ["Wie viel weniger schlafen Nachtarbeiter im Schnitt?","Ein bis zwei Stunden",["Vier Stunden","Gar nicht weniger","Eine halbe Stunde"]],
  ["Was hilft auf dem Heimweg nach der Nachtschicht?","Eine Sonnenbrille",["Ein Kaffee","Laute Musik","Ein Spaziergang in der Sonne"]],
  ["Wie lange dauert es, bis die Hälfte des Koffeins abgebaut ist?","Etwa sechs Stunden",["Eine Stunde","Zwölf Stunden","Zwei Tage"]],
  ["Was ist sein wichtigster Rat?","Schlaf so ernst nehmen wie Ernährung und Sport",["Mehr Kaffee trinken","Nachts nicht arbeiten","Schlaftabletten nehmen"]]]},
{ id: "p09", level: "C2", title: "Die Kunst des Small Talks", people: ["Host","Olivia"], lines: [
  ["Host","Welcome to 'Between the Lines', the podcast about the unwritten rules of English. Olivia, you coach international managers. Why does small talk matter so much?","Willkommen bei „Between the Lines“, dem Podcast über die ungeschriebenen Regeln des Englischen. Olivia, du coachst internationale Führungskräfte. Warum ist Small Talk so wichtig?"],
  ["Olivia","Because in much of the English-speaking world, it's how trust is built. Many of my German clients see it as a waste of time – they'd rather get straight down to business. But skipping it can come across as cold, even rude, and that may well cost you the deal before you've opened your laptop.","Weil im englischsprachigen Raum vielerorts so Vertrauen entsteht. Viele meiner deutschen Kunden halten es für Zeitverschwendung – sie würden lieber gleich zur Sache kommen. Aber wer es auslässt, wirkt schnell kalt oder sogar unhöflich, und das kann einen den Deal kosten, bevor man den Laptop aufgeklappt hat."],
  ["Host","So what makes good small talk?","Was macht guten Small Talk aus?"],
  ["Olivia","Safe topics, genuine curiosity and, crucially, not taking it too literally. When someone asks 'How are you?', they don't want your medical history. 'Not bad, thanks – busy week. And you?' is perfect. Weather, travel, sport, food – all fine. Politics, religion and salaries are best avoided.","Unverfängliche Themen, echtes Interesse und, ganz wichtig, es nicht zu wörtlich nehmen. Wenn jemand „How are you?“ fragt, will er nicht deine Krankengeschichte hören. „Nicht schlecht, danke – anstrengende Woche. Und dir?“ ist perfekt. Wetter, Reisen, Sport, Essen – alles gut. Politik, Religion und Gehälter meidet man besser."],
  ["Host","Is there a typical mistake you see?","Gibt es einen typischen Fehler, den du beobachtest?"],
  ["Olivia","Answering questions with a single word. 'Did you have a good flight?' – 'Yes.' Full stop. To a German, that's a perfectly adequate answer. To a Brit or an American, it sounds like you'd rather not talk. Add a detail and a question back: 'Yes, thanks – a bit bumpy over the Channel, though. Do you travel much for work?'","Fragen mit einem einzigen Wort beantworten. „Hatten Sie einen guten Flug?“ – „Ja.“ Punkt. Für Deutsche eine völlig ausreichende Antwort. Für Briten oder Amerikaner klingt es, als wolle man lieber nicht reden. Fügen Sie ein Detail und eine Gegenfrage hinzu: „Ja, danke – über dem Ärmelkanal etwas holprig. Reisen Sie beruflich viel?“"],
  ["Host","And how do you know when small talk is over?","Und woran merkt man, dass der Small Talk vorbei ist?"],
  ["Olivia","Usually the host signals it: 'Right, shall we get started?' or 'Anyway, I suppose we'd better crack on.' Had you jumped in with the agenda five minutes earlier, it would have felt abrupt. Let them set the pace.","Meist signalisiert es der Gastgeber: „So, wollen wir anfangen?“ oder „Jedenfalls sollten wir wohl loslegen.“ Wäre man fünf Minuten früher mit der Tagesordnung gekommen, hätte das abrupt gewirkt. Lassen Sie den anderen das Tempo bestimmen."],
  ["Host","Any final tip?","Ein letzter Tipp?"],
  ["Olivia","Prepare two or three questions in advance, just as you would prepare figures for a meeting. It sounds artificial, but it takes the pressure off – and, before long, it'll feel entirely natural.","Bereiten Sie zwei, drei Fragen vor, so wie Sie Zahlen für eine Besprechung vorbereiten. Das klingt künstlich, nimmt aber den Druck – und schon bald fühlt es sich völlig natürlich an."]],
  questions: [
  ["Warum ist Small Talk laut Olivia wichtig?","So entsteht Vertrauen",["Er spart Zeit","Er ist gesetzlich üblich","Er ersetzt die Tagesordnung"]],
  ["Welche Themen sollte man meiden?","Politik, Religion, Gehälter",["Wetter und Reisen","Sport und Essen","Hobbys"]],
  ["Was ist ein typischer Fehler?","Mit nur einem Wort antworten",["Zu viel über das Wetter reden","Zu früh kommen","Zu leise sprechen"]],
  ["Wer beendet normalerweise den Small Talk?","Der Gastgeber",["Der Gast","Der Jüngste","Niemand – man redet einfach weiter"]],
  ["Was empfiehlt sie zur Vorbereitung?","Zwei, drei Fragen vorher überlegen",["Witze auswendig lernen","Small Talk vermeiden","Nur zuhören"]]]},
{ id: "p10", level: "C2", title: "Wenn Englisch die Firmensprache wird", people: ["Host","Thomas","Aisha"], lines: [
  ["Host","On today's 'Between the Lines', we're looking at what happens when a company switches its official language to English. Thomas works for a German engineering firm that did exactly that three years ago; Aisha is an intercultural trainer. Thomas, how did it go?","Heute bei „Between the Lines“ schauen wir, was passiert, wenn eine Firma ihre offizielle Sprache auf Englisch umstellt. Thomas arbeitet bei einem deutschen Maschinenbauer, der genau das vor drei Jahren getan hat; Aisha ist interkulturelle Trainerin. Thomas, wie lief es?"],
  ["Thomas","To put it mildly, the first months were bumpy. Meetings that used to take thirty minutes took an hour, and people who'd always been confident suddenly went quiet. Some of our best engineers barely said a word.","Um es milde auszudrücken: Die ersten Monate waren holprig. Besprechungen, die früher dreißig Minuten dauerten, dauerten eine Stunde, und Leute, die immer selbstsicher waren, wurden plötzlich still. Einige unserer besten Ingenieure sagten kaum ein Wort."],
  ["Aisha","That's a pattern I see time and again. When people work in a second language, they often lose part of their professional identity. You go from being the expert to sounding like a beginner, and that's deeply uncomfortable.","Das ist ein Muster, das ich immer wieder sehe. Wer in einer Zweitsprache arbeitet, verliert oft einen Teil seiner beruflichen Identität. Man ist plötzlich nicht mehr der Experte, sondern klingt wie ein Anfänger, und das ist zutiefst unangenehm."],
  ["Host","How did the company respond?","Wie hat die Firma reagiert?"],
  ["Thomas","Initially, not very well – there was a one-size-fits-all online course that nobody finished. What eventually worked was far more pragmatic: small groups, real work situations, and a rule that nobody gets corrected in meetings unless they ask to be.","Zunächst nicht besonders gut – es gab einen Einheits-Onlinekurs, den niemand beendet hat. Was schließlich funktionierte, war viel pragmatischer: kleine Gruppen, echte Arbeitssituationen und die Regel, dass niemand in Besprechungen korrigiert wird, außer er bittet darum."],
  ["Aisha","That last point is crucial. Fear of losing face is the single biggest barrier. Were I advising any company considering this step, I'd insist that managers go first – if the boss makes mistakes openly, everyone else relaxes.","Der letzte Punkt ist entscheidend. Die Angst, das Gesicht zu verlieren, ist das größte Hindernis. Würde ich eine Firma beraten, die diesen Schritt erwägt, würde ich darauf bestehen, dass die Führungskräfte vorangehen – wenn der Chef offen Fehler macht, entspannen sich alle anderen."],
  ["Host","Is it worth it in the end?","Lohnt es sich am Ende?"],
  ["Thomas","On balance, yes. We now have colleagues from fourteen countries, and our customers abroad notice the difference. But I'd be lying if I said it was painless. It cost time, money and, for some people, a fair amount of stress.","Alles in allem ja. Wir haben jetzt Kollegen aus vierzehn Ländern, und unsere Kunden im Ausland merken den Unterschied. Aber ich würde lügen, wenn ich sagte, es sei schmerzlos gewesen. Es hat Zeit, Geld und manche Leute einiges an Stress gekostet."],
  ["Aisha","And perhaps the most important lesson: nobody needs perfect English. What matters is being understood – and being patient with each other. In international teams, the native speakers often need training too: to speak more slowly and drop the idioms.","Und vielleicht die wichtigste Lehre: Niemand braucht perfektes Englisch. Wichtig ist, verstanden zu werden – und geduldig miteinander zu sein. In internationalen Teams brauchen oft auch die Muttersprachler Training: langsamer sprechen und die Redewendungen weglassen."]],
  questions: [
  ["Was passierte in den ersten Monaten?","Besprechungen dauerten länger und viele wurden still",["Alle waren begeistert","Viele kündigten sofort","Nichts änderte sich"]],
  ["Was verlieren Menschen laut Aisha in einer Zweitsprache oft?","Einen Teil ihrer beruflichen Identität",["Ihre Muttersprache","Ihren Job","Ihr Gehalt"]],
  ["Was hat schließlich funktioniert?","Kleine Gruppen, echte Arbeitssituationen, keine Korrekturen in Meetings",["Ein Onlinekurs für alle","Strenge Tests","Englisch nur für Führungskräfte"]],
  ["Was rät Aisha Firmen?","Führungskräfte sollen vorangehen",["Nur Muttersprachler einstellen","Englisch langsam einführen","Fehler bestrafen"]],
  ["Wer braucht laut Aisha auch Training?","Die Muttersprachler",["Nur die Chefs","Nur neue Mitarbeiter","Niemand"]]]},
{ id: "p11", level: "A1", title: "Meine Familie", people: ["Host","Anna"], lines: [
  ["Host","Hello and welcome to 'Easy English Stories'. My guest today is Anna. Hi, Anna!","Hallo und willkommen bei „Easy English Stories“. Mein Gast heute ist Anna. Hallo, Anna!"],
  ["Anna","Hello! Nice to be here.","Hallo! Schön, hier zu sein."],
  ["Host","Anna, where are you from?","Anna, woher kommst du?"],
  ["Anna","I'm from Hamburg, in Germany. But now I live in Dublin.","Ich komme aus Hamburg in Deutschland. Aber jetzt wohne ich in Dublin."],
  ["Host","Tell us about your family.","Erzähl uns von deiner Familie."],
  ["Anna","I have a small family. I have one brother. His name is Paul. He is twenty-five and he is a cook.","Ich habe eine kleine Familie. Ich habe einen Bruder. Er heißt Paul. Er ist fünfundzwanzig und er ist Koch."],
  ["Host","And your parents?","Und deine Eltern?"],
  ["Anna","My mother is a teacher. My father works in a bank. They live in Hamburg with our cat, Mia.","Meine Mutter ist Lehrerin. Mein Vater arbeitet in einer Bank. Sie wohnen mit unserer Katze Mia in Hamburg."],
  ["Host","Do you see your family often?","Siehst du deine Familie oft?"],
  ["Anna","Not very often. I call my mother every Sunday. And at Christmas I fly home.","Nicht sehr oft. Ich rufe meine Mutter jeden Sonntag an. Und an Weihnachten fliege ich nach Hause."],
  ["Host","That's nice. Thank you, Anna!","Das ist schön. Danke, Anna!"],
  ["Anna","Thank you. Bye!","Danke. Tschüss!"]],
  questions: [
  ["Wo wohnt Anna jetzt?","In Dublin",["In Hamburg","In London","In Berlin"]],
  ["Was ist ihr Bruder von Beruf?","Koch",["Lehrer","Bankangestellter","Arzt"]],
  ["Wo arbeitet ihr Vater?","In einer Bank",["In einer Schule","In einem Restaurant","Zu Hause"]],
  ["Wann ruft Anna ihre Mutter an?","Jeden Sonntag",["Jeden Morgen","Jeden Freitag","Nur an Weihnachten"]],
  ["Wie heißt die Katze?","Mia",["Paul","Anna","Max"]]]},
{ id: "p12", level: "A1", title: "Ein ganz normaler Tag", people: ["Host","Tom"], lines: [
  ["Host","Welcome back! Today Tom tells us about his day. Hi, Tom!","Willkommen zurück! Heute erzählt uns Tom von seinem Tag. Hallo, Tom!"],
  ["Tom","Hi! My day is very normal, but okay!","Hi! Mein Tag ist ganz normal, aber okay!"],
  ["Host","What time do you get up?","Wann stehst du auf?"],
  ["Tom","I get up at six o'clock. I have a shower and then I drink a big cup of tea.","Ich stehe um sechs Uhr auf. Ich dusche und dann trinke ich eine große Tasse Tee."],
  ["Host","Not coffee?","Keinen Kaffee?"],
  ["Tom","No, I don't like coffee. I eat toast with butter, too.","Nein, ich mag keinen Kaffee. Ich esse auch Toast mit Butter."],
  ["Host","How do you go to work?","Wie kommst du zur Arbeit?"],
  ["Tom","I go by bike. It takes twenty minutes. I work in a shop. I sell shoes.","Ich fahre mit dem Fahrrad. Es dauert zwanzig Minuten. Ich arbeite in einem Laden. Ich verkaufe Schuhe."],
  ["Host","And in the evening?","Und am Abend?"],
  ["Tom","I finish work at five. In the evening I cook dinner and watch TV. On Tuesdays I play football with friends.","Ich habe um fünf Feierabend. Abends koche ich und schaue fern. Dienstags spiele ich mit Freunden Fußball."],
  ["Host","And when do you go to bed?","Und wann gehst du ins Bett?"],
  ["Tom","At ten o'clock. I'm always tired!","Um zehn Uhr. Ich bin immer müde!"]],
  questions: [
  ["Wann steht Tom auf?","Um sechs Uhr",["Um sieben Uhr","Um fünf Uhr","Um zehn Uhr"]],
  ["Was trinkt Tom am Morgen?","Tee",["Kaffee","Saft","Milch"]],
  ["Wie fährt er zur Arbeit?","Mit dem Fahrrad",["Mit dem Bus","Mit dem Auto","Zu Fuß"]],
  ["Was verkauft Tom?","Schuhe",["Bücher","Fahrräder","Kleidung"]],
  ["Was macht er dienstags?","Er spielt Fußball",["Er kocht für Freunde","Er geht schwimmen","Er arbeitet länger"]]]},
{ id: "p13", level: "A1", title: "Meine neue Wohnung", people: ["Host","Lucy"], lines: [
  ["Host","Hello and welcome. Lucy has a new flat. Congratulations, Lucy!","Hallo und willkommen. Lucy hat eine neue Wohnung. Glückwunsch, Lucy!"],
  ["Lucy","Thank you! I'm very happy.","Danke! Ich bin sehr glücklich."],
  ["Host","Where is it?","Wo ist sie?"],
  ["Lucy","It's in the city centre, near the park. There is a bus stop in front of the house.","Sie ist im Stadtzentrum, in der Nähe vom Park. Vor dem Haus ist eine Bushaltestelle."],
  ["Host","How many rooms are there?","Wie viele Zimmer gibt es?"],
  ["Lucy","There are two rooms: a bedroom and a living room. And there is a small kitchen and a bathroom.","Es gibt zwei Zimmer: ein Schlafzimmer und ein Wohnzimmer. Und es gibt eine kleine Küche und ein Bad."],
  ["Host","Is there a balcony?","Gibt es einen Balkon?"],
  ["Lucy","Yes! The balcony is my favourite place. I have three plants there, and in the morning I sit there with my breakfast.","Ja! Der Balkon ist mein Lieblingsplatz. Ich habe dort drei Pflanzen, und morgens sitze ich dort mit meinem Frühstück."],
  ["Host","Is the flat expensive?","Ist die Wohnung teuer?"],
  ["Lucy","A little. But it's quiet and very bright. And my neighbours are friendly. They are an old couple with a dog.","Ein bisschen. Aber sie ist ruhig und sehr hell. Und meine Nachbarn sind freundlich. Sie sind ein altes Ehepaar mit einem Hund."],
  ["Host","That sounds perfect. Thank you, Lucy!","Das klingt perfekt. Danke, Lucy!"]],
  questions: [
  ["Wo liegt die Wohnung?","Im Stadtzentrum, nahe dem Park",["Am Stadtrand","Am Bahnhof","Auf dem Land"]],
  ["Wie viele Zimmer hat sie (ohne Küche und Bad)?","Zwei",["Eins","Drei","Vier"]],
  ["Was ist Lucys Lieblingsplatz?","Der Balkon",["Die Küche","Das Schlafzimmer","Der Park"]],
  ["Was macht sie morgens auf dem Balkon?","Sie frühstückt",["Sie liest Zeitung","Sie telefoniert","Sie macht Sport"]],
  ["Wer sind ihre Nachbarn?","Ein älteres Ehepaar mit Hund",["Eine Familie mit Kindern","Studenten","Ein junger Mann mit Katze"]]]},
{ id: "p14", level: "A2", title: "Urlaub mit Hindernissen", people: ["Host","Jonas"], lines: [
  ["Host","Welcome back to 'Easy English Stories'. Jonas, you were on holiday last month. Where did you go?","Willkommen zurück bei „Easy English Stories“. Jonas, du warst letzten Monat im Urlaub. Wo warst du?"],
  ["Jonas","I went to Portugal with my girlfriend. We stayed in a small town by the sea for ten days.","Ich war mit meiner Freundin in Portugal. Wir waren zehn Tage in einer kleinen Stadt am Meer."],
  ["Host","Sounds great. Did everything go well?","Klingt toll. Ist alles gut gelaufen?"],
  ["Jonas","Not at the start! Our flight was three hours late, and then the airline lost my suitcase.","Am Anfang nicht! Unser Flug hatte drei Stunden Verspätung, und dann hat die Fluggesellschaft meinen Koffer verloren."],
  ["Host","Oh no! What did you do?","Oh nein! Was hast du gemacht?"],
  ["Jonas","I had only the clothes I was wearing. So on the first day I bought a T-shirt, shorts and a toothbrush. My girlfriend thought it was very funny.","Ich hatte nur die Kleidung, die ich anhatte. Also habe ich am ersten Tag ein T-Shirt, Shorts und eine Zahnbürste gekauft. Meine Freundin fand das sehr lustig."],
  ["Host","Did you get your suitcase back?","Hast du deinen Koffer zurückbekommen?"],
  ["Jonas","Yes, after three days. A man brought it to our hotel. I was so happy!","Ja, nach drei Tagen. Ein Mann hat ihn zu unserem Hotel gebracht. Ich war so froh!"],
  ["Host","And the rest of the holiday?","Und der Rest des Urlaubs?"],
  ["Jonas","It was wonderful. We swam every day, ate a lot of fish and rented bikes. One evening we watched the sunset from an old castle.","Er war wunderbar. Wir sind jeden Tag geschwommen, haben viel Fisch gegessen und Fahrräder gemietet. An einem Abend haben wir den Sonnenuntergang von einer alten Burg aus gesehen."],
  ["Host","Would you go back?","Würdest du wieder hinfahren?"],
  ["Jonas","Definitely. But next time I'll pack some clothes in my hand luggage!","Auf jeden Fall. Aber nächstes Mal packe ich ein paar Sachen ins Handgepäck!"]],
  questions: [
  ["Wie lange waren Jonas und seine Freundin in Portugal?","Zehn Tage",["Eine Woche","Drei Tage","Zwei Wochen"]],
  ["Was war das erste Problem?","Der Flug hatte drei Stunden Verspätung",["Das Hotel war ausgebucht","Es hat geregnet","Er hat seinen Pass vergessen"]],
  ["Wann kam der Koffer an?","Nach drei Tagen",["Am selben Abend","Nach einer Woche","Gar nicht"]],
  ["Was haben sie an einem Abend gemacht?","Den Sonnenuntergang von einer Burg aus angeschaut",["Eine Bootstour gemacht","Im Restaurant getanzt","Ein Konzert besucht"]],
  ["Was macht Jonas nächstes Mal anders?","Er packt Kleidung ins Handgepäck",["Er fährt mit dem Zug","Er bucht ein anderes Hotel","Er fliegt allein"]]]},
{ id: "p15", level: "B1", title: "Wie ein Hund mein Leben verändert hat", people: ["Host","Claire"], lines: [
  ["Host","Hello and welcome. My guest today is Claire, who says a dog changed her life. Claire, that's a big claim!","Hallo und willkommen. Mein Gast heute ist Claire, die sagt, ein Hund habe ihr Leben verändert. Claire, das ist eine starke Aussage!"],
  ["Claire","It is, but it's true. Two years ago I was working from home, and some weeks I hardly left my flat. I felt quite lonely.","Ist es, aber es stimmt. Vor zwei Jahren habe ich von zu Hause gearbeitet, und in manchen Wochen habe ich meine Wohnung kaum verlassen. Ich habe mich ziemlich einsam gefühlt."],
  ["Host","So you decided to get a dog?","Also hast du beschlossen, dir einen Hund zu holen?"],
  ["Claire","Not straight away. A friend suggested it, but I was worried it would be too much responsibility. In the end I adopted Bruno from an animal shelter. He was five years old and nobody wanted him because he was a bit shy.","Nicht sofort. Eine Freundin hat es vorgeschlagen, aber ich hatte Sorge, dass es zu viel Verantwortung wäre. Am Ende habe ich Bruno aus dem Tierheim adoptiert. Er war fünf Jahre alt, und niemand wollte ihn, weil er etwas schüchtern war."],
  ["Host","How did things change?","Wie hat sich das verändert?"],
  ["Claire","First of all, I had to go outside three times a day, whatever the weather. I started to feel fitter, and I slept better too.","Zuallererst musste ich dreimal am Tag raus, bei jedem Wetter. Ich habe mich fitter gefühlt und auch besser geschlafen."],
  ["Host","And socially?","Und sozial?"],
  ["Claire","That was the biggest surprise. Dog owners talk to each other all the time. I've met more people in my area in two years than in the five years before. One of them is now my best friend.","Das war die größte Überraschung. Hundebesitzer reden ständig miteinander. Ich habe in zwei Jahren mehr Leute in meiner Gegend kennengelernt als in den fünf Jahren davor. Eine davon ist jetzt meine beste Freundin."],
  ["Host","Were there any difficulties?","Gab es Schwierigkeiten?"],
  ["Claire","Of course. Bruno was afraid of loud noises, so the first New Year's Eve was terrible. And holidays are harder to plan now. But I wouldn't change it.","Natürlich. Bruno hatte Angst vor lauten Geräuschen, deshalb war das erste Silvester furchtbar. Und Urlaube sind jetzt schwerer zu planen. Aber ich würde es nicht ändern."],
  ["Host","Any advice for people who are thinking about getting a dog?","Ein Rat für Leute, die überlegen, sich einen Hund zu holen?"],
  ["Claire","Be honest about your time. A dog isn't a cure for loneliness on its own – but if you can give it a good life, it will give you a lot back.","Sei ehrlich, was deine Zeit angeht. Ein Hund allein ist kein Heilmittel gegen Einsamkeit – aber wenn du ihm ein gutes Leben geben kannst, gibt er dir viel zurück."]],
  questions: [
  ["Wie ging es Claire vor zwei Jahren?","Sie fühlte sich einsam und kam kaum aus der Wohnung",["Sie hatte zu viel Stress im Büro","Sie war gerade umgezogen","Sie war krank"]],
  ["Woher kommt Bruno?","Aus dem Tierheim",["Von einem Züchter","Von einer Freundin","Von der Straße"]],
  ["Warum wollte ihn vorher niemand?","Er war etwas schüchtern",["Er war zu alt","Er war krank","Er bellte zu viel"]],
  ["Was war die größte Überraschung?","Sie hat viele Leute in ihrer Gegend kennengelernt",["Sie schläft besser","Bruno war schnell erzogen","Es war billiger als gedacht"]],
  ["Was rät Claire?","Ehrlich prüfen, ob man genug Zeit hat",["Nur junge Hunde nehmen","Erst einen Kurs machen","Nie in Urlaub fahren"]]]},
{ id: "p16", level: "B2", title: "Ein Jahr Vier-Tage-Woche", people: ["Host","Mike"], lines: [
  ["Host","Welcome to 'Work Talk'. Mike runs a small design agency with twelve employees, and a year ago they switched to a four-day week. Mike, why did you take the risk?","Willkommen bei „Work Talk“. Mike leitet eine kleine Designagentur mit zwölf Mitarbeitenden, und vor einem Jahr haben sie auf die Vier-Tage-Woche umgestellt. Mike, warum bist du das Risiko eingegangen?"],
  ["Mike","Honestly, we were losing good people. Two designers left within six months, and both mentioned burnout. Raising salaries wasn't an option, so we looked for something else that would make us attractive.","Ehrlich gesagt haben wir gute Leute verloren. Zwei Designer sind innerhalb von sechs Monaten gegangen, und beide haben Burnout erwähnt. Gehälter zu erhöhen war keine Option, also haben wir nach etwas anderem gesucht, das uns attraktiv macht."],
  ["Host","Did you cut pay or extend the working days?","Habt ihr das Gehalt gekürzt oder die Arbeitstage verlängert?"],
  ["Mike","Neither. Same pay, same eight-hour days, just Fridays off. The deal was that output shouldn't drop. We agreed to review it after six months.","Weder noch. Gleiches Gehalt, gleiche Acht-Stunden-Tage, nur freitags frei. Die Abmachung war, dass die Leistung nicht sinken darf. Wir haben vereinbart, es nach sechs Monaten zu überprüfen."],
  ["Host","How did you make that work?","Wie habt ihr das hinbekommen?"],
  ["Mike","Mostly by cutting meetings. We had a meeting culture that ate up about a day a week. Now internal meetings are limited to thirty minutes, and Tuesday and Thursday mornings are meeting-free for focused work.","Vor allem, indem wir Meetings gekürzt haben. Wir hatten eine Meetingkultur, die etwa einen Tag pro Woche gefressen hat. Jetzt sind interne Meetings auf dreißig Minuten begrenzt, und Dienstag- und Donnerstagvormittag sind meetingfrei für konzentriertes Arbeiten."],
  ["Host","And the results?","Und die Ergebnisse?"],
  ["Mike","Revenue went up by about eight percent, sick days roughly halved, and nobody has quit since. But I don't want to oversell it – some of that growth came from a big new client.","Der Umsatz ist um etwa acht Prozent gestiegen, die Krankheitstage haben sich ungefähr halbiert, und seitdem hat niemand gekündigt. Aber ich will es nicht schönreden – ein Teil des Wachstums kam von einem großen neuen Kunden."],
  ["Host","What were the downsides?","Was waren die Nachteile?"],
  ["Mike","Clients sometimes expect us on Fridays, so we set up a rota: one person is on call each Friday and gets a different day off instead. And the four days are intense. A couple of people said they feel more pressure than before.","Kunden erwarten uns manchmal freitags, deshalb haben wir einen Dienstplan: Jeden Freitag hat eine Person Bereitschaft und bekommt dafür einen anderen Tag frei. Und die vier Tage sind intensiv. Ein paar Leute haben gesagt, dass sie mehr Druck spüren als vorher."],
  ["Host","Would you recommend it to other companies?","Würdest du es anderen Firmen empfehlen?"],
  ["Mike","Only if they're prepared to change how they work, not just when. If you simply squeeze five days of chaos into four, it'll fail.","Nur wenn sie bereit sind zu ändern, wie sie arbeiten, nicht nur wann. Wenn man einfach fünf Tage Chaos in vier quetscht, scheitert es."]],
  questions: [
  ["Warum hat Mike die Vier-Tage-Woche eingeführt?","Gute Leute haben wegen Burnout gekündigt",["Die Kunden haben es verlangt","Um Gehaltskosten zu sparen","Weil es ein Gesetz gab"]],
  ["Was blieb gleich?","Gehalt und Länge der Arbeitstage",["Nur das Gehalt","Nur die Meetings","Die Arbeit am Freitag"]],
  ["Wie haben sie die Zeit eingespart?","Durch kürzere und weniger Meetings",["Durch Überstunden","Durch neue Software","Durch weniger Kunden"]],
  ["Warum ist Mike bei den Zahlen vorsichtig?","Ein Teil des Wachstums kam von einem neuen Großkunden",["Die Zahlen sind geschätzt","Es gab mehr Krankheitstage","Zwei Leute haben gekündigt"]],
  ["Wie lösen sie das Problem mit Kunden am Freitag?","Eine Person hat Bereitschaft und nimmt einen anderen Tag frei",["Freitags ist das Telefon aus","Mike arbeitet allein","Kunden müssen bis Montag warten"]]]},
{ id: "p17", level: "C1", title: "Warum wir Dinge aufschieben", people: ["Host","Dr. Reyes"], lines: [
  ["Host","Welcome to 'Mind Matters'. We all put things off – tax returns, difficult emails, the gym. My guest, psychologist Dr. Elena Reyes, argues that procrastination has very little to do with laziness. Dr. Reyes, what is it about, then?","Willkommen bei „Mind Matters“. Wir alle schieben Dinge auf – Steuererklärungen, schwierige E-Mails, das Fitnessstudio. Mein Gast, die Psychologin Dr. Elena Reyes, meint, Aufschieben habe sehr wenig mit Faulheit zu tun. Dr. Reyes, worum geht es denn dann?"],
  ["Dr. Reyes","Largely about managing emotions. When a task makes us feel anxious, bored or inadequate, avoiding it gives us instant relief. The problem is that the relief is short-lived, and the guilt that follows makes the task even more unpleasant the next time round.","Größtenteils um den Umgang mit Gefühlen. Wenn uns eine Aufgabe ängstlich, gelangweilt oder unzulänglich fühlen lässt, verschafft uns das Vermeiden sofort Erleichterung. Das Problem ist, dass die Erleichterung nur kurz anhält, und die Schuldgefühle danach machen die Aufgabe beim nächsten Mal noch unangenehmer."],
  ["Host","So it's a vicious circle.","Also ein Teufelskreis."],
  ["Dr. Reyes","Exactly. And people who procrastinate a lot often respond by being harsh with themselves, which, counterintuitively, makes things worse. Studies on students found that those who forgave themselves for procrastinating before one exam procrastinated less before the next.","Genau. Und Menschen, die viel aufschieben, reagieren oft damit, hart mit sich selbst zu sein, was – entgegen der Intuition – alles schlimmer macht. Studien mit Studierenden haben gezeigt, dass diejenigen, die sich das Aufschieben vor einer Prüfung verziehen, vor der nächsten weniger aufgeschoben haben."],
  ["Host","That's surprising. What about perfectionism?","Das überrascht. Was ist mit Perfektionismus?"],
  ["Dr. Reyes","It plays a big part. If the standard you set is impossibly high, starting means confronting the gap between what you want to produce and what you can actually produce today. Not starting keeps the fantasy intact.","Er spielt eine große Rolle. Wenn der Maßstab, den man sich setzt, unerreichbar hoch ist, bedeutet Anfangen, sich mit der Lücke zu konfrontieren zwischen dem, was man schaffen will, und dem, was man heute tatsächlich schaffen kann. Nicht anzufangen hält die Fantasie aufrecht."],
  ["Host","So what actually helps?","Was hilft denn tatsächlich?"],
  ["Dr. Reyes","Shrinking the first step until it feels almost silly. Not 'write the report', but 'open the document and write one bad sentence'. Once you've started, the emotional barrier tends to drop. Another technique is to notice the feeling – 'I'm avoiding this because I'm worried it won't be good enough' – without acting on it.","Den ersten Schritt so klein machen, dass er sich fast albern anfühlt. Nicht „den Bericht schreiben“, sondern „das Dokument öffnen und einen schlechten Satz schreiben“. Hat man einmal angefangen, sinkt die emotionale Hürde meist. Eine andere Technik ist, das Gefühl wahrzunehmen – „Ich vermeide das, weil ich Angst habe, dass es nicht gut genug wird“ – ohne danach zu handeln."],
  ["Host","Do productivity apps help?","Helfen Produktivitäts-Apps?"],
  ["Dr. Reyes","They can, but they often treat the symptom. If the underlying issue is fear of failure, a nicer to-do list won't fix it. Ironically, organising your apps can become a sophisticated form of procrastination in itself.","Können sie, aber sie behandeln oft das Symptom. Wenn das eigentliche Problem Angst vor dem Scheitern ist, löst eine schönere To-do-Liste es nicht. Ironischerweise kann das Organisieren der Apps selbst zu einer raffinierten Form des Aufschiebens werden."]],
  questions: [
  ["Worum geht es beim Aufschieben laut Dr. Reyes vor allem?","Um den Umgang mit unangenehmen Gefühlen",["Um Faulheit","Um schlechtes Zeitmanagement","Um fehlende Intelligenz"]],
  ["Was zeigte die Studie mit Studierenden?","Wer sich selbst verzieh, schob vor der nächsten Prüfung weniger auf",["Strenge Selbstkritik hilft am meisten","Aufschieben verbessert die Noten","Apps reduzieren das Aufschieben"]],
  ["Warum fangen Perfektionisten oft nicht an?","Anfangen zeigt die Lücke zwischen Anspruch und Können",["Sie haben zu viele Aufgaben","Sie sind mit dem Ergebnis immer zufrieden","Sie warten auf Hilfe"]],
  ["Was empfiehlt sie als ersten Schritt?","Einen lächerlich kleinen ersten Schritt wählen",["Den ganzen Tag dafür blocken","Sich eine Belohnung versprechen","Die Aufgabe abgeben"]],
  ["Was sagt sie über Produktivitäts-Apps?","Sie behandeln oft nur das Symptom",["Sie lösen das Problem vollständig","Sie sind immer schädlich","Sie helfen nur Studierenden"]]]},
{ id: "p18", level: "C2", title: "Die Sprache der Werbung", people: ["Host","Eleanor","James"], lines: [
  ["Host","Welcome to 'Between the Lines'. Today we're unpicking the language of advertising with linguist Eleanor Walsh and former copywriter James Okafor. James, let's start with you – you spent fifteen years writing slogans. Is it fair to say your job was to mislead people?","Willkommen bei „Between the Lines“. Heute nehmen wir die Sprache der Werbung auseinander, mit der Linguistin Eleanor Walsh und dem früheren Werbetexter James Okafor. James, fangen wir mit dir an – du hast fünfzehn Jahre lang Slogans geschrieben. Kann man sagen, dass es dein Job war, Leute in die Irre zu führen?"],
  ["James","I'd quibble with 'mislead'. Our job was to make claims that were technically defensible yet emotionally persuasive. Whether that's misleading depends on how charitable you're feeling.","Bei „in die Irre führen“ würde ich widersprechen. Unser Job war es, Aussagen zu machen, die technisch vertretbar und zugleich emotional überzeugend waren. Ob das irreführend ist, hängt davon ab, wie wohlwollend man gerade gestimmt ist."],
  ["Eleanor","And that gap is precisely where linguists get interested. Take a word like 'helps'. 'Helps reduce wrinkles' commits the advertiser to almost nothing, yet listeners tend to hear 'reduces wrinkles'. The hedge does the legal work; the listener's brain does the rest.","Und genau diese Lücke interessiert Linguisten. Nehmen Sie ein Wort wie „hilft“. „Hilft, Falten zu reduzieren“ verpflichtet den Werbenden zu fast nichts, und doch hören Zuhörer eher „reduziert Falten“. Die Abschwächung erledigt die juristische Arbeit, das Gehirn des Zuhörers den Rest."],
  ["James","Guilty as charged. 'Up to fifty percent off' was another favourite. One item in the shop might be half price – the rest, ten percent.","Schuldig im Sinne der Anklage. „Bis zu fünfzig Prozent Rabatt“ war auch ein Favorit. Ein Artikel im Laden ist vielleicht zum halben Preis – der Rest zehn Prozent."],
  ["Host","Eleanor, are there subtler techniques that people don't notice at all?","Eleanor, gibt es subtilere Techniken, die gar nicht auffallen?"],
  ["Eleanor","Presupposition is the classic one. 'Why not treat yourself to something special this weekend?' never asserts that you deserve a treat – it simply assumes it, and assumptions are far harder to argue with than claims. Comparatives without a reference point work similarly: 'cleaner', 'faster', 'better' – than what, exactly?","Die Präsupposition ist der Klassiker. „Warum gönnen Sie sich dieses Wochenende nicht etwas Besonderes?“ behauptet nie, dass Sie eine Belohnung verdienen – es setzt es einfach voraus, und Voraussetzungen sind viel schwerer anzufechten als Behauptungen. Komparative ohne Bezugspunkt funktionieren ähnlich: „sauberer“, „schneller“, „besser“ – als was eigentlich?"],
  ["James","What outsiders underestimate is how much of it is rhythm rather than meaning. A slogan has to survive being half-heard on a radio in a noisy kitchen. We'd sacrifice accuracy for a better cadence without a second thought.","Was Außenstehende unterschätzen, ist, wie viel davon Rhythmus statt Bedeutung ist. Ein Slogan muss überleben, wenn man ihn in einer lauten Küche im Radio nur halb hört. Wir haben Genauigkeit ohne zu zögern für einen besseren Rhythmus geopfert."],
  ["Host","Has regulation caught up?","Hat die Regulierung aufgeholt?"],
  ["Eleanor","Partly. Outright false claims are policed reasonably well, but the law is ill-equipped to deal with implicature – what's suggested rather than said. You can't easily ban an inference.","Teilweise. Glatte Falschaussagen werden einigermaßen gut kontrolliert, aber das Recht ist schlecht gerüstet für Implikaturen – für das, was angedeutet statt gesagt wird. Eine Schlussfolgerung kann man nicht so leicht verbieten."],
  ["James","Which is why the best defence isn't legislation, it's literacy. Once you've learned to spot the hedge, you can't unsee it – and frankly, that ruined television for me.","Deshalb ist der beste Schutz nicht Gesetzgebung, sondern Bildung. Wenn man einmal gelernt hat, die Abschwächung zu erkennen, sieht man sie immer – und ehrlich gesagt hat mir das das Fernsehen verdorben."]],
  questions: [
  ["Wie beschreibt James seinen früheren Job?","Aussagen machen, die rechtlich vertretbar, aber emotional überzeugend sind",["Bewusst falsche Behauptungen aufstellen","Produkte objektiv beschreiben","Werbung juristisch prüfen"]],
  ["Was zeigt das Beispiel „hilft, Falten zu reduzieren“?","Eine Abschwächung, die Zuhörer als feste Zusage verstehen",["Ein verbotenes Werbeversprechen","Einen wissenschaftlichen Nachweis","Einen falschen Vergleich"]],
  ["Was ist eine Präsupposition in der Werbung?","Etwas wird stillschweigend vorausgesetzt statt behauptet",["Ein Vergleich mit der Konkurrenz","Eine Preisangabe mit Sternchen","Ein Reim im Slogan"]],
  ["Was ist laut James bei Slogans oft wichtiger als Genauigkeit?","Der Rhythmus",["Die Länge","Die Farbe","Der Preis"]],
  ["Was ist laut beiden der beste Schutz?","Die Fähigkeit, solche Tricks zu erkennen",["Strengere Gesetze","Weniger Fernsehen","Werbeverbote"]]]}
];
